llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C49"],
      "claim": "Urapidil, a methoxyaryl piperazine drug, has absolute oral bioavailability of 72% in healthy volunteers, directly supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Atazanavir, a high-molecular-weight peptidic drug, shows oral bioavailability >90% with food in humans, supporting high F despite large size and complexity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "GSK1322322, a methoxy-aniline pyrimidine piperidine, has absolute F of 77% fed and 57% fasted in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Bosentan, containing methoxy, sulfonamide, pyrimidine and pyridyl groups, has absolute F approximately 46-50% in healthy subjects, supporting high F for a sulfonamide heteroaromatic.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C50"],
      "claim": "Sulpiride, a methoxy benzamide sulfonamide, has mean oral F about 35% in humans, supporting F≥20% despite a wide interindividual range.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Sildenafil, a methoxy/sulfonamide heteroaromatic, has absolute F of 38-41% in humans, supporting F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Suvorexant, a heteroaromatic piperidine drug, has mean F of 82% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Acalabrutinib, a pyridine/aminopyrimidine kinase inhibitor, has absolute F of 25% in humans, still above the 20% threshold and supporting the high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Rigosertib had absolute F of 13.9% in fed MDS patients, below threshold, but 34.8% fasting; this fed low value reflects food/formulation effects rather than intrinsic low F.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues with direct absolute oral bioavailability measurements support F≥20%, with most values between 25% and 82%; the only sub-20 value (rigosertib fed, 13.9%) is contradicted by its fasting F of 35% and appears to be a food/formulation effect. The mixed physicochemical prior is outweighed by consistent, transferable experimental evidence, so the query is predicted high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule.",
    "Food effects and formulation dependence for the query are unknown.",
    "Potential solubility/dissolution and metabolic liabilities of the primary aromatic amine and sulfonamide are not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

